function better(a: number[], b: number[]) {
  return a.filter((v, i) => v > b[i]).length;
}
function range(a: number[]) {
  return `${sgn(Math.round(Math.min(...a)))} to ${sgn(Math.round(Math.max(...a)))}`;
}
const N_BASE = "Baseline Trend Policy";
const N_OPT = "Baseline + Our Optimization";
const N_F = "Baseline + Our Optimization + Our Entry filters";
const N_ML = "Baseline + Our Optimization + Our Entry filters + Our ML";
const N_MLS = "Baseline + Our Optimization + Our Entry filters + Our ML + variable lot";
const NAMING = "Baseline Trend Policy = committed config.py with fixed parameters; every other line is a SAIL Lab proposal built on it. Optimization = walk-forward re-optimization on a 60-day window. Entry filters = no entries 10:00-13:00 New York (US/Europe overlap) and only in the direction of today's move.";
function schedRows(label: string, s: Sched): string[][] {
  const f = s.opt_filters_phase_totals, nf = s.opt_no_filter_phase_totals, ml = s.ml_phase_totals, mls = s.ml_sized_phase_totals;
  const n = f.length;
  return [
    [`${N_OPT} (${label})`, sgn(Math.round(sum(nf) / n)), String(Math.round(s.opt_no_filter_dd)), range(nf), "-"],
    [`${N_F} (${label})`, sgn(Math.round(sum(f) / n)), String(Math.round(s.opt_filters_dd)), range(f), `${better(f, nf)} of ${n}`],
    [`${N_ML} (${label})`, sgn(Math.round(sum(ml) / n)), String(Math.round(s.ml_dd)), range(ml), `${better(ml, f)} of ${n}`],
    [`${N_MLS} 1-2x (${label})`, sgn(Math.round(sum(mls) / n)), String(Math.round(s.ml_sized_dd)), range(mls), `${better(mls, f)} of ${n}`],
  ];
}
const S5 = opt_live_net_W60_R5, S20 = opt_live_net_W60_R20;
const avgP = (a: number[]) => Math.round(sum(a) / a.length);
const ddOf = (cum: number[]) => {
  let peak = 0;
  return cum.map((v) => {
    peak = Math.max(peak, v);
    return Math.round((v - peak) * 10) / 10;
  });
};
